steps.code:
mutation {
  draftOrderCreate(input: {
    lineItems: [{ variantId: "gid://shopify/ProductVariant/1", quantity: 1 }]
  }) {
    draftOrder { id }
    userErrors { field message }
  }
}

query {
  order(id: "gid://shopify/Order/1") {
    fulfillmentOrders(first: 5) {
      nodes { id status assignedLocation { name } }
    }
  }
}

mutation {
  fulfillmentCreate(fulfillment: {
    lineItemsByFulfillmentOrder: [{
      fulfillmentOrderId: "gid://shopify/FulfillmentOrder/1"
    }],
    trackingInfo: { number: "BR123456789", company: "Correios" }
  }) { fulfillment { id status } userErrors { field message } }
}

mutation {
  refundCreate(input: {
    orderId: "gid://shopify/Order/1",
    refundLineItems: [{ lineItemId: "gid://shopify/LineItem/1", quantity: 1 }],
    transactions: [{
      orderId: "gid://shopify/Order/1",
      gateway: "bogus",
      kind: REFUND,
      amount: "49.90"
    }]
  }) { refund { id } userErrors { field message } }
}

mutation {
  draftOrderCreate(input: {
    lineItems: [
      { variantId: "gid://shopify/ProductVariant/1", quantity: 1 },
      { variantId: "gid://shopify/ProductVariant/2", quantity: 2 }
    ]
  }) { draftOrder { id } }
}
